package dev.pocketengine.features.local.project;

import dev.pocketengine.features.workspace.VersionedWorkspace;
import java.util.*;
import org.json.*;

/** Explicit raw source deletion with frozen native before bytes, never a model Base64 writer. */
final class ProjectByteDelete {
    static final String CONTRACT="pocketworld.exact-source-byte-delete.v1";
    private ProjectByteDelete(){}
    static boolean matches(JSONObject file){return CONTRACT.equals(file.optString("bytePatchContract"));}
    private static Set<String> keys(JSONObject value){Set<String> result=new TreeSet<>();value.keys().forEachRemaining(result::add);return result;}
    private static String path(String value){String path=VersionedWorkspace.path(value);if(!ProjectSources.sourcePath(path))throw new SecurityException("delete_bytes仅支持同工作副本source路径，不删目录/依赖/构建输出");return path;}
    private static int count(Object value){if(!(value instanceof Integer||value instanceof Long)||((Number)value).longValue()<0||((Number)value).longValue()>ProjectExactPatch.MAX_TEXT_BYTES)throw new SecurityException("原字节删除大小须为0至256KiB准确整数");return ((Number)value).intValue();}
    private static byte[] decode(JSONObject file,String field)throws Exception{String value=file.getString(field);if(value.length()>((ProjectExactPatch.MAX_TEXT_BYTES+2)/3)*4)throw new SecurityException("原字节删除/恢复超过计划字节预算");byte[] bytes;try{bytes=Base64.getDecoder().decode(value);}catch(IllegalArgumentException invalid){throw new SecurityException("原完整字节不是Base64",invalid);}if(bytes.length>ProjectExactPatch.MAX_TEXT_BYTES||!Base64.getEncoder().encodeToString(bytes).equals(value))throw new SecurityException("原字节不是canonical完整正文");return bytes;}
    static JSONObject prepare(Map<String,byte[]> frozen,JSONObject edit)throws Exception{
        if(!keys(edit).equals(Set.of("action","path","expectedHash"))||!"delete_bytes".equals(edit.optString("action")))throw new IllegalArgumentException("delete_bytes只接收path/刚读expectedHash，不接收正文、Base64、递归或权限参数");String target=path(edit.getString("path"));byte[] bytes=frozen.get(target);if(bytes==null||!ProjectSources.sha256(bytes).equals(edit.getString("expectedHash")))throw new SecurityException("原字节删除需准确既有文件和整SHA");if(bytes.length>ProjectExactPatch.MAX_TEXT_BYTES)throw new IllegalArgumentException("此原私有计划只删除256KiB内source原件，未截断");return row(target,bytes,false,null);
    }
    private static JSONObject row(String target,byte[] bytes,boolean restore,String operation)throws Exception{
        String sha=ProjectSources.sha256(bytes);JSONObject source=new JSONObject().put("path",target).put("sha256",sha).put("bytes",bytes.length).put("source","original_frozen_snapshot");JSONObject change=new JSONObject().put("kind",restore?"restore_original_deleted_bytes":"delete_bytes").put("sourceHash",sha).put("sourceBytes",bytes.length).put(restore?"restoresOriginalDeletedSource":"deletesExistingSource",true);
        JSONObject file=new JSONObject().put("path",target).put("action",restore?"create":"delete").put("encoding","base64").put("bytePatchContract",CONTRACT).put("deleteDirection",restore?"restore":"forward").put("expectedHash",restore?"absent":sha).put("afterHash",restore?sha:"absent").put("beforeContentBase64",restore?"":Base64.getEncoder().encodeToString(bytes)).put("contentBase64",restore?Base64.getEncoder().encodeToString(bytes):"").put("beforeBytes",restore?0:bytes.length).put("afterBytes",restore?bytes.length:0).put("deletedSource",source).put("changes",new JSONArray().put(change));if(restore)file.put("revertsOperationId",ProjectBuildPlan.identity(operation));return file;
    }
    static byte[][] validated(JSONObject file)throws Exception{
        boolean restore="restore".equals(file.optString("deleteDirection"));Set<String> fields=new TreeSet<>(Set.of("path","action","encoding","bytePatchContract","deleteDirection","expectedHash","afterHash","beforeContentBase64","contentBase64","beforeBytes","afterBytes","deletedSource","changes"));if(restore)fields.add("revertsOperationId");if(!keys(file).equals(fields)||!matches(file)||!"base64".equals(file.optString("encoding"))||!(restore||"forward".equals(file.optString("deleteDirection")))||!(restore?"create":"delete").equals(file.optString("action")))throw new SecurityException("原字节删除/条件恢复类型不明确，不能成为通用二进制写入");
        String target=path(file.getString("path"));JSONObject source=file.getJSONObject("deletedSource");if(!keys(source).equals(Set.of("path","sha256","bytes","source"))||!target.equals(path(source.getString("path")))||!"original_frozen_snapshot".equals(source.optString("source")))throw new SecurityException("删除原件描述不是同路径的固定来源");byte[] before=decode(file,"beforeContentBase64"),after=decode(file,"contentBase64"),original=restore?after:before;String sha=ProjectSources.sha256(original);if((restore?before:after).length!=0||count(file.get("beforeBytes"))!=before.length||count(file.get("afterBytes"))!=after.length||count(source.get("bytes"))!=original.length||!sha.equals(source.optString("sha256"))||!(restore?"absent":sha).equals(file.optString("expectedHash"))||!(restore?sha:"absent").equals(file.optString("afterHash")))throw new SecurityException("删除/恢复完整原字节、SHA、大小或存在状态不同");
        JSONArray changes=file.getJSONArray("changes");if(changes.length()!=1)throw new SecurityException("原字节删除需唯一准确变化");JSONObject change=changes.getJSONObject(0);String flag=restore?"restoresOriginalDeletedSource":"deletesExistingSource";if(!keys(change).equals(Set.of("kind","sourceHash","sourceBytes",flag))||!(restore?"restore_original_deleted_bytes":"delete_bytes").equals(change.optString("kind"))||!sha.equals(change.optString("sourceHash"))||count(change.get("sourceBytes"))!=original.length||!Boolean.TRUE.equals(change.opt(flag)))throw new SecurityException("原字节删除审阅与原件不同");if(restore)ProjectBuildPlan.identity(file.getString("revertsOperationId"));return new byte[][]{before,after};
    }
    /** Restore bytes originate only in the original TaskStore revert factory, never current model input. */
    static void requirePlanSource(JSONObject core,JSONObject step,JSONObject file)throws Exception{
        byte[][] bytes=validated(file);boolean restore="restore".equals(file.getString("deleteDirection"));JSONObject payload=step.getJSONObject("payload");if(!"patchFiles".equals(step.optString("localCommand"))||!(restore?"revert_operation":"patch").equals(core.optString("intent"))||!core.getString("checkoutId").equals(payload.optString("checkoutId"))||!core.getString("sourceDigest").equals(payload.optString("expectedSourceDigest"))||restore&&!file.getString("revertsOperationId").equals(payload.optString("revertsOperationId")))throw new SecurityException("原字节删除/恢复不属于同一原补丁操作");boolean found=false;long total=0;JSONArray manifest=core.getJSONArray("sourceManifest");for(int i=0;i<manifest.length();i++){JSONObject source=manifest.getJSONObject(i);total+=source.getLong("bytes");if(!file.getString("path").equals(source.getString("path")))continue;if(restore)throw new SecurityException("恢复目标已在当前source清单，不覆盖后续新文件");if(!file.getString("expectedHash").equals(source.getString("sha256"))||bytes[0].length!=count(source.get("bytes")))throw new SecurityException("删除before字节并非原固定source清单");found=true;}if(!restore&&!found)throw new SecurityException("删除原件没有准确固定source来源");if(restore&&(manifest.length()>=ProjectSources.MAX_FILES||total+bytes[1].length>ProjectSources.MAX_TOTAL_BYTES))throw new SecurityException("恢复后超过原source文件数/16MiB预算，未生成部分恢复");
    }
    static JSONObject reverse(JSONObject original,String operation)throws Exception{byte[][] bytes=validated(original);if(!"forward".equals(original.getString("deleteDirection")))throw new SecurityException("原删除的恢复不递归撤销；需要删除时重新明确delete_bytes");return row(original.getString("path"),bytes[0],true,operation);}
}
